PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS departments (id INTEGER PRIMARY KEY, department_code TEXT NOT NULL UNIQUE, department_name TEXT NOT NULL, description TEXT, head_employee_id INTEGER REFERENCES employees(id), status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS designations (id INTEGER PRIMARY KEY, designation_code TEXT NOT NULL UNIQUE, designation_name TEXT NOT NULL, job_description TEXT, job_grade TEXT, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS employees (id INTEGER PRIMARY KEY, employee_number TEXT NOT NULL UNIQUE, payroll_number TEXT UNIQUE, national_id_number TEXT UNIQUE, first_name TEXT NOT NULL, middle_name TEXT, last_name TEXT NOT NULL, gender TEXT, date_of_birth TEXT, institutional_email TEXT, personal_email TEXT, phone_number TEXT, alternative_phone_number TEXT, postal_address TEXT, physical_address TEXT, department_id INTEGER REFERENCES departments(id), designation_id INTEGER REFERENCES designations(id), employment_status TEXT NOT NULL DEFAULT 'active', employment_type TEXT NOT NULL DEFAULT 'permanent', date_joined TEXT, contract_end_date TEXT, supervisor_employee_id INTEGER REFERENCES employees(id), profile_photo_path TEXT, created_by INTEGER, updated_by INTEGER, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS roles (id INTEGER PRIMARY KEY, role_name TEXT NOT NULL UNIQUE, description TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, employee_id INTEGER UNIQUE REFERENCES employees(id), username TEXT NOT NULL UNIQUE, email TEXT UNIQUE, password_hash TEXT NOT NULL, is_active INTEGER NOT NULL DEFAULT 1, is_staff INTEGER NOT NULL DEFAULT 0, last_login TEXT, failed_login_attempts INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS user_roles (id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), role_id INTEGER NOT NULL REFERENCES roles(id), assigned_by INTEGER REFERENCES users(id), assigned_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, expires_at TEXT, status TEXT NOT NULL DEFAULT 'active', UNIQUE(user_id,role_id));
CREATE TABLE IF NOT EXISTS employment_records (id INTEGER PRIMARY KEY, employee_id INTEGER NOT NULL REFERENCES employees(id), department_id INTEGER REFERENCES departments(id), designation_id INTEGER REFERENCES designations(id), employment_type TEXT, job_grade TEXT, start_date TEXT NOT NULL, end_date TEXT, salary_grade TEXT, supervisor_employee_id INTEGER REFERENCES employees(id), change_reason TEXT, approved_by INTEGER REFERENCES users(id), created_by INTEGER REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS employee_documents (id INTEGER PRIMARY KEY, employee_id INTEGER NOT NULL REFERENCES employees(id), document_type TEXT NOT NULL, document_title TEXT NOT NULL, original_filename TEXT NOT NULL, stored_filename TEXT NOT NULL, mime_type TEXT, file_size INTEGER, document_reference TEXT, issue_date TEXT, expiry_date TEXT, uploaded_by INTEGER REFERENCES users(id), uploaded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, document_status TEXT NOT NULL DEFAULT 'active', notes TEXT);
CREATE TABLE IF NOT EXISTS leave_types (id INTEGER PRIMARY KEY, leave_code TEXT NOT NULL UNIQUE, leave_name TEXT NOT NULL, description TEXT, default_annual_entitlement REAL NOT NULL DEFAULT 0, maximum_consecutive_days REAL, minimum_notice_days INTEGER NOT NULL DEFAULT 0, requires_attachment INTEGER NOT NULL DEFAULT 0, attachment_rules TEXT, allow_half_day INTEGER NOT NULL DEFAULT 0, carry_forward_allowed INTEGER NOT NULL DEFAULT 0, maximum_carry_forward_days REAL, paid_or_unpaid TEXT NOT NULL DEFAULT 'paid', eligibility_rules TEXT, status TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS leave_requests (id INTEGER PRIMARY KEY, request_reference TEXT NOT NULL UNIQUE, employee_id INTEGER NOT NULL REFERENCES employees(id), leave_type_id INTEGER NOT NULL REFERENCES leave_types(id), start_date TEXT NOT NULL, end_date TEXT NOT NULL, half_day_indicator INTEGER NOT NULL DEFAULT 0, requested_working_days REAL NOT NULL, reason TEXT NOT NULL, attachment_required INTEGER NOT NULL DEFAULT 0, request_status TEXT NOT NULL DEFAULT 'Submitted', current_approval_stage TEXT NOT NULL DEFAULT 'Supervisor', submitted_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, cancelled_at TEXT, cancellation_reason TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS leave_approvals (id INTEGER PRIMARY KEY, leave_request_id INTEGER NOT NULL REFERENCES leave_requests(id), approval_stage TEXT NOT NULL CHECK(approval_stage IN ('Supervisor','HR','Final Approver')), approver_user_id INTEGER NOT NULL REFERENCES users(id), decision TEXT NOT NULL DEFAULT 'pending', comments TEXT, assigned_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, action_at TEXT, delegated_to_user_id INTEGER REFERENCES users(id), delegation_reason TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(leave_request_id,approval_stage));
CREATE TABLE IF NOT EXISTS leave_transactions (id INTEGER PRIMARY KEY, employee_id INTEGER NOT NULL REFERENCES employees(id), leave_type_id INTEGER NOT NULL REFERENCES leave_types(id), leave_request_id INTEGER REFERENCES leave_requests(id), transaction_type TEXT NOT NULL, transaction_date TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, days_credited REAL NOT NULL DEFAULT 0, days_debited REAL NOT NULL DEFAULT 0, balance_after REAL NOT NULL, reference_number TEXT, description TEXT, created_by INTEGER REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS leave_balances (id INTEGER PRIMARY KEY, employee_id INTEGER NOT NULL REFERENCES employees(id), leave_type_id INTEGER NOT NULL REFERENCES leave_types(id), period_year INTEGER NOT NULL, opening_balance REAL NOT NULL DEFAULT 0, accrued REAL NOT NULL DEFAULT 0, taken REAL NOT NULL DEFAULT 0, adjusted REAL NOT NULL DEFAULT 0, current_balance REAL NOT NULL DEFAULT 0, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(employee_id,leave_type_id,period_year));
CREATE TABLE IF NOT EXISTS audit_logs (id INTEGER PRIMARY KEY, user_id INTEGER REFERENCES users(id), action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT, old_values TEXT, new_values TEXT, ip_address TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_employee_search ON employees(employee_number, department_id, designation_id, employment_status);
CREATE INDEX IF NOT EXISTS idx_leave_queue ON leave_requests(request_status,current_approval_stage,submitted_at);
CREATE INDEX IF NOT EXISTS idx_leave_employee ON leave_requests(employee_id,start_date,end_date);
CREATE INDEX IF NOT EXISTS idx_audit_entity ON audit_logs(entity_type,entity_id,created_at);
